#!/usr/bin/env python3
"""Write Expected Parrot report assets (CSS + LaTeX header + Lua filter) into a writeup directory."""

import base64
from pathlib import Path

_ROOT = Path(__file__).resolve().parent
_CSS_FILE = _ROOT / "report.css"
_LATEX_HEADER_FILE = _ROOT / "report_header.tex"
_LOGO_B64 = ""
_LUA_FILTER_FILE = _ROOT / "fix-table-widths.lua"


def create_css(writeup_dir: str = "writeup") -> Path:
    """Copy report.css into writeup_dir/report.css. Returns the output path."""
    dest = Path(writeup_dir) / "report.css"
    dest.parent.mkdir(parents=True, exist_ok=True)
    dest.write_text(_CSS_FILE.read_text())
    return dest


def create_latex_header(writeup_dir: str = "writeup") -> Path:
    """Copy report_header.tex into writeup_dir/report_header.tex. Returns the output path."""
    dest = Path(writeup_dir) / "report_header.tex"
    dest.parent.mkdir(parents=True, exist_ok=True)
    dest.write_text(_LATEX_HEADER_FILE.read_text())
    return dest


def create_logo(writeup_dir: str = "writeup") -> Path:
    """Copy ep_logo.pdf into writeup_dir/ep_logo.pdf. Returns the output path."""
    dest = Path(writeup_dir) / "ep_logo.pdf"
    dest.parent.mkdir(parents=True, exist_ok=True)
    dest.write_bytes(base64.b64decode(_LOGO_B64))
    return dest


def create_lua_filter(writeup_dir: str = "writeup") -> Path:
    """Copy fix-table-widths.lua into writeup_dir/fix-table-widths.lua. Returns the output path."""
    dest = Path(writeup_dir) / "fix-table-widths.lua"
    dest.parent.mkdir(parents=True, exist_ok=True)
    dest.write_text(_LUA_FILTER_FILE.read_text())
    return dest


if __name__ == "__main__":
    import sys

    target = sys.argv[1] if len(sys.argv) > 1 else "writeup"
    out_css = create_css(target)
    out_tex = create_latex_header(target)
    out_logo = create_logo(target)
    out_lua = create_lua_filter(target)
    print(f"Wrote {out_css}")
    print(f"Wrote {out_tex}")
    print(f"Wrote {out_logo}")
    print(f"Wrote {out_lua}")
